<script setup>import {computed} from 'vue';import {store,saveCart} from '../main';const total=computed(()=>store.cart.reduce((s,i)=>s+i.price*i.quantity,0));function remove(i){store.cart.splice(i,1);saveCart()}function qty(i,d){store.cart[i].quantity=Math.max(1,store.cart[i].quantity+d);saveCart()}</script>
<template><section class="simple-page"><div class="breadcrumbs">Home / Cart</div><h1>Shopping Cart</h1><p>Review your selected items before checking out.</p><div v-if="!store.cart.length" class="empty">Your cart is empty. <router-link to="/shop">Continue shopping →</router-link></div><div v-else class="cart-layout"><div class="cart-items"><article v-for="(i,index) in store.cart" class="cart-item"><div class="mini-art">V</div><div class="grow"><b>{{i.name}}</b><span>SKU: {{i.sku}}</span></div><div>${{i.price.toFixed(2)}}</div><div class="qty"><button @click="qty(index,-1)">−</button>{{i.quantity}}<button @click="qty(index,1)">+</button></div><button class="text-button" @click="remove(index)">Remove</button></article></div><aside class="summary"><span>Cart Summary</span><h2>${{total.toFixed(2)}}</h2><p>Shipping and tax calculated at checkout.</p><router-link class="btn primary full" to="/checkout">Proceed to Checkout</router-link></aside></div></section></template>
